const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.contentHistory)) staticData.contentHistory = [];
if (!Number.isInteger(staticData.categoryIndex)) staticData.categoryIndex = 0;

const categories = ['science','space','animals','human body','psychology','history','technology','nature','geography','inventions','food origins','language','money and economics','mysteries and unusual facts','records and comparisons','ocean','weather and natural phenomena','everyday objects','transportation','art and culture'];
const history = staticData.contentHistory.slice(-100);
const previous = history.length ? history.map((x,i) => `${i+1}. CATEGORY: ${x.category}
TITLE: ${x.title}
HOOK: ${x.hook}
TOPIC: ${x.topic}`).join('
') : 'No previous content exists yet.';

return categories.slice(staticData.categoryIndex, staticData.categoryIndex + 10).map((category, i) => {
  const realCategory = categories[(staticData.categoryIndex + i) % categories.length];
  const system = `You are an expert viral YouTube Shorts scriptwriter.

The channel publishes surprising, accurate and verifiable Did You Know facts.

ASSIGNED CATEGORY: ${realCategory}

Return ONLY one JSON object with EXACTLY these keys:
hook - one short pattern-interrupt sentence and first narration line.
script - 70-90 words. Start with hook. Conversational, fast and punchy. Explain ONE surprising fact. End with a short question or follow-for-more line. No emojis, hashtags or stage directions.
title - maximum 90 characters and MUST end with #Shorts.
description - 2-3 natural sentences followed by a new line containing 5 relevant hashtags.
tags - array of 8-12 lowercase keyword strings.
query - 1-2 word English stock-video search query.
voice - exactly one of: af_bella, af_heart, am_adam, am_michael.
topic - concise description of the core fact.
category - exactly the assigned category.

RULES:
1. Fact must be substantially different from previous content.
2. Never reuse previous facts with different wording.
3. Never reuse previous title or hook.
4. Stay inside assigned category.
5. Prefer surprising, understandable and verifiable facts.
6. One strong fact only.
7. Suitable for approximately 35-55 seconds.

PREVIOUS CONTENT TO AVOID:
${previous}`;

  return {
    json: {
      batchNumber: i + 1,
      category: realCategory,
      body: {
        model: 'llama-3.3-70b-versatile',
        temperature: 1.0,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: `Generate ONE completely fresh ${realCategory} Short. Respond with JSON only.` }
        ]
      }
    }
  };
});

staticData.categoryIndex = (staticData.categoryIndex + 10) % categories.length;

const items = $input.all();
const output = [];

for (let index = 0; index < items.length; index++) {
  const res = items[index].json;
  const content = res.choices?.[0]?.message?.content;
  if (!content) throw new Error(`Groq returned no content for item ${index + 1}`);

  let data;
  try {
    data = JSON.parse(content);
  } catch (e) {
    throw new Error(`Invalid Groq JSON for item ${index + 1}: ${content.slice(0, 500)}`);
  }

  if (!data.script || !data.title || !data.hook || !data.topic) {
    throw new Error(`Missing required fields for item ${index + 1}`);
  }

  data.tags = Array.isArray(data.tags) ? data.tags : [];
  data.voice = data.voice || 'af_bella';
  data.query = data.query || 'abstract';
  data.category = data.category || 'general';

  if (!data.title.toLowerCase().includes('#shorts')) {
    data.title = data.title.trim() + ' #Shorts';
  }

  const wordCount = String(data.script).trim().split(/\s+/).length;
  if (wordCount < 65 || wordCount > 100) {
    throw new Error(`SCRIPT_LENGTH_REJECTED item ${index + 1}: ${wordCount} words`);
  }

  output.push({
    json: {
      ...data,
      batchNumber: index + 1,
      requestedCategory: data.category
    }
  });
}

return output;

const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.contentHistory)) staticData.contentHistory = [];

const history = staticData.contentHistory;

function normalize(text) {
  return String(text || '').toLowerCase().replace(/#shorts/g, '').replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
}

function words(text) {
  return new Set(normalize(text).split(' ').filter(w => w.length > 3));
}

function similarity(a, b) {
  const A = words(a), B = words(b);
  if (!A.size || !B.size) return 0;
  let intersection = 0;
  for (const word of A) if (B.has(word)) intersection++;
  return intersection / Math.max(1, Math.min(A.size, B.size));
}

const input = $input.all();
const output = [];

for (const itemWrapper of input) {
  const item = itemWrapper.json;
  const candidate = [item.title, item.hook, item.topic, item.script].join(' ');
  let duplicate = false;

  for (const old of history.slice(-100)) {
    if (normalize(item.title) === normalize(old.title) || normalize(item.hook) === normalize(old.hook) || similarity(item.topic, old.topic) >= 0.60) {
      duplicate = true;
      break;
    }

    const oldContent = [old.title, old.hook, old.topic, old.script].join(' ');
    if (similarity(candidate, oldContent) >= 0.58) {
      duplicate = true;
      break;
    }
  }

  if (duplicate) {
    throw new Error(`DUPLICATE_CONTENT_REJECTED: batch ${item.batchNumber}`);
  }

  history.push({
    title: item.title,
    hook: item.hook,
    topic: item.topic,
    script: item.script,
    query: item.query,
    category: item.category,
    createdAt: new Date().toISOString()
  });

  output.push({ json: item });
}

while (history.length > 100) history.shift();
return output;

return $input.all().map((wrapper, index) => {
  const item = wrapper.json;
  const runId = `${String($execution.id || Date.now())}_${item.batchNumber || index + 1}`;
  const runDir = `/data/${runId}`;
  const job = {
    script: item.script,
    query: item.query,
    voice: item.voice,
    scenes: [
      {
        text_en: item.script,
        text_ar: item.script,
        pexels_query: item.query
      }
    ]
  };
  const jobB64 = Buffer.from(JSON.stringify(job), 'utf8').toString('base64');

  return {
    json: {
      ...item,
      runId,
      runDir,
      jobB64
    }
  };
});
